-- Generated by scripts/build_compiled.py from src/fraudrules/rules/synthetic-identity/si-001-ssn-multiple-identities.yaml. Do not edit.
-- SI-001 One SSN presented with more than one name or date of birth
SELECT
  'SI-001' AS rule_id,
  'applications' AS anchor_table,
  a.id AS anchor_id
FROM applications AS a
JOIN applications AS b
  ON b.ssn_token = a.ssn_token AND b.ts <= a.ts
WHERE
  1 = 1 AND 1 = 1
GROUP BY
  a.id
HAVING
  (
    COUNT(DISTINCT b.name_token) >= 2 OR COUNT(DISTINCT b.dob_day) >= 2
  );
